import {InputDirectionResolver,INPUT_DIRECTION_POLICY,StructuredRichContentOwner} from './foundation/structured.js';
import {PlatformInputDirectionBridge,NO_PLATFORM_INPUT_DIRECTION_BRIDGE} from './foundation/contracts/platform-input-direction-bridge.js';
import {sanitizeStructuredInlineHTML,STRUCTURED_RICH_SANITIZATION_POLICY} from './foundation/structured/sanitization-policy.js';
import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {createNoteContentDirectionFixture} from './adapters/note-content-direction-fixture.js';
import {FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES} from './adapters/library-fixtures.js';

const assert=(value,message='assertion failed')=>{if(!value)throw Error(message)};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const throws=(fn,token)=>{let message='';try{fn()}catch(error){message=String(error?.message||error)}assert(message.includes(token),`expected ${token}, got ${message}`)};
const test=(tests,id,run)=>{try{const evidence=run();tests.push({id,status:'PASS',evidence})}catch(error){tests.push({id,status:'FAIL',error:String(error?.stack||error)})}};
const libraryBundle={FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES,initialDocumentId:'KU-D05-0021'};

export function runW4CDirectionRichContentTests(){
  const tests=[];
  test(tests,'w4c.direction.platform-rtl',()=>{const r=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'rtl')}).resolve({content:''});assert(r.direction==='rtl'&&r.source==='PLATFORM_OS_KEYBOARD_HINT'&&r.bridgeUsed);return r});
  test(tests,'w4c.direction.platform-ltr',()=>{const r=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'ltr')}).resolve({content:''});assert(r.direction==='ltr'&&r.source==='PLATFORM_OS_KEYBOARD_HINT'&&r.bridgeUsed);return r});
  test(tests,'w4c.direction.unknown-hint-explicit-fallback',()=>{const r=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'unknown')}).resolve({content:'',fallbackDirection:'ltr'});assert(r.direction==='ltr'&&r.source==='EXPLICIT_FALLBACK'&&r.bridgeCapability.code==='PLATFORM_DIRECTION_HINT_UNKNOWN');return r});
  test(tests,'w4c.direction.bridge-absence-truthful',()=>{const r=new InputDirectionResolver({bridge:NO_PLATFORM_INPUT_DIRECTION_BRIDGE}).resolve({content:''});assert(!r.bridgeCapability.available&&r.bridgeCapability.code==='PLATFORM_DIRECTION_BRIDGE_ABSENT'&&r.fallbackUsed);return r});
  test(tests,'w4c.direction.persisted-rtl-wins',()=>{const r=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'ltr')}).resolve({persistedDirection:'rtl',content:'English content'});assert(r.direction==='rtl'&&r.persistedWon&&!r.bridgeUsed);return r});
  test(tests,'w4c.direction.persisted-ltr-wins',()=>{const r=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'rtl')}).resolve({persistedDirection:'ltr',content:'محتوى عربي'});assert(r.direction==='ltr'&&r.persistedWon&&!r.bridgeUsed);return r});
  test(tests,'w4c.direction.empty-structured-and-note-agree',()=>{const resolver=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'ltr')}),s=resolver.initializeEmptyStructuredBlock({id:'empty-s',type:'paragraph',html:''}),n=resolver.initializeEmptyNoteContent({id:'empty-n',html:''});assert(s.block.dir==='ltr'&&n.content.dir==='ltr'&&s.resolution.direction===n.resolution.direction);return {structured:s,note:n}});
  test(tests,'w4c.direction.mixed-content-no-domain-language-inference',()=>{const content='English first ثم العربية then API';const a=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'rtl')}).resolve({content,surface:'library'}),b=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'rtl')}).resolve({content,surface:'learn'});assert(a.direction==='rtl'&&b.direction==='rtl'&&!a.semanticInference&&!b.semanticInference&&!a.contentInspectedForLanguage&&!b.contentInspectedForLanguage);return {a,b}});
  test(tests,'w4c.direction.policy-fallback-central',()=>{const r=new InputDirectionResolver().resolve({content:'abc العربية'});assert(r.direction===INPUT_DIRECTION_POLICY.fallbackDirection&&r.source==='POLICY_FALLBACK');return r});
  test(tests,'w4c.direction.valid-explicit-rtl-fallback-provenance',()=>{const r=new InputDirectionResolver({bridge:NO_PLATFORM_INPUT_DIRECTION_BRIDGE}).resolve({content:'',fallbackDirection:'rtl'});assert(r.direction==='rtl'&&r.source==='EXPLICIT_FALLBACK');return r});
  test(tests,'w4c.direction.invalid-auto-fallback-uses-policy-provenance',()=>{const r=new InputDirectionResolver({bridge:NO_PLATFORM_INPUT_DIRECTION_BRIDGE}).resolve({content:'',fallbackDirection:'auto'});assert(r.direction===INPUT_DIRECTION_POLICY.fallbackDirection&&r.source==='POLICY_FALLBACK');return r});
  test(tests,'w4c.direction.invalid-bogus-fallback-uses-policy-provenance',()=>{const r=new InputDirectionResolver({bridge:NO_PLATFORM_INPUT_DIRECTION_BRIDGE}).resolve({content:'',fallbackDirection:'bogus'});assert(r.direction===INPUT_DIRECTION_POLICY.fallbackDirection&&r.source==='POLICY_FALLBACK');return r});
  test(tests,'w4c.rich.safe-inline-formatting',()=>{const owner=new StructuredRichContentOwner(),bold=owner.formatInline('<admin>','bold'),code=owner.formatInline('a < b && c > d','code');assert(bold.html==='<strong>&lt;admin&gt;</strong>');assert(code.html.includes('<bdi dir="ltr">')&&code.html.includes('<code class="inline-code">a &lt; b &amp;&amp; c &gt; d</code>'));return {bold,code}});
  test(tests,'w4c.rich.unsafe-html-sanitized',()=>{const v=sanitizeStructuredInlineHTML('<strong onclick="evil()">ok</strong><script>attack()</script><img src=x onerror=evil()>tail');assert(v.safe&&v.changed&&!/script|onerror|onclick|<img/i.test(v.html)&&v.html==='<strong>ok</strong>tail');return v});
  test(tests,'w4c.rich.no-script-event-handler-leakage',()=>{const owner=new StructuredRichContentOwner(),vectors=['<svg onload=evil()><script>x</script></svg>','<bdi dir="rtl" onmouseover="x">س</bdi>','<code style="background:url(javascript:x)">x</code>'];const results=vectors.map(v=>owner.sanitizeInline(v));assert(results.every(r=>!/<\/?(?:script|svg)|\son[a-z]+\s*=|javascript\s*:/i.test(r.html)));return results});
  test(tests,'w4c.rich.code-raw-copy-fidelity',()=>{const raw='const x = "<tag>";\n\tif (x) return `قيمة:${x}`;\r\n',owner=new StructuredRichContentOwner(),p=owner.projectBlock({id:'code-1',type:'code',html:raw});assert(p.rawText===raw&&p.copyText===raw&&p.html.includes('&lt;tag&gt;')&&p.direction==='ltr');return {rawBytes:new TextEncoder().encode(raw).length,projectedBytes:p.rawByteLength,copyEqual:p.copyText===raw}});
  test(tests,'w4c.rich.code-dangerous-looking-source-remains-raw-not-active-html',()=>{const learn=createStructuredConsumerAdapter('learn'),portable={kind:STRUCTURED_RICH_SANITIZATION_POLICY.portableKind,version:1,blocks:[{id:'code-danger',type:'code',html:'<script>alert(1)</script>\nconst u="javascript:x";'}]};const canonical=learn.richContentOwner.canonicalClipboardFromPortable(portable,{documentId:'code-doc',domainKind:'portable'});const block=canonical.payload.blocks[0];assert(block.codeText==='<script>alert(1)</script>\nconst u="javascript:x";'&&!/<script/i.test(block.html)&&canonical.validation.owner==='StructuredClipboardTrustOwner');const projection=learn.richContentOwner.projectBlock(block);assert(projection.rawText===block.codeText&&projection.copyText===block.codeText);return {html:block.html,raw:block.codeText,validation:canonical.validation}});
  test(tests,'w4c.rich.bidi-isolation',()=>{const owner=new StructuredRichContentOwner(),r=owner.isolateInline('policy.can(subject, action, resource)','ltr');assert(r.html==='<bdi dir="ltr">policy.can(subject, action, resource)</bdi>');return r});
  test(tests,'w4c.rich.persisted-direction-not-overridden',()=>{const owner=new StructuredRichContentOwner({directionResolver:new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'rtl')})}),p=owner.projectBlock({id:'p',type:'paragraph',html:'English',dir:'ltr'});assert(p.direction==='ltr'&&p.directionResolution.persistedWon);return p.directionResolution});
  test(tests,'w4c.rich.library-learn-real-consumers',()=>{const library=createStructuredConsumerAdapter('library',libraryBundle),learn=createStructuredConsumerAdapter('learn');assert(library.richContentOwner?.owner==='StructuredRichContentOwner'&&learn.richContentOwner?.owner==='StructuredRichContentOwner');const lb=library.projectRichBlock('blk-d05-p1'),ln=learn.projectRichBlock('learn-p1');assert(lb.sanitized&&ln.sanitized&&library.descriptor().richContentOwner==='StructuredRichContentOwner'&&learn.descriptor().inputDirectionOwner==='InputDirectionResolver');return {library:{owner:library.owner,block:lb},learn:{owner:learn.owner,block:ln}}});
  test(tests,'w4c.rich.note-content-fixture-reuse-no-sticky-owner',()=>{const resolver=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'rtl')}),note=createNoteContentDirectionFixture({resolver,id:'note-proof',html:''});assert(note.owner==='NoteContentDirectionFixtureAdapter'&&!note.stickyNoteWindowOwnerImplemented&&note.content.dir==='rtl'&&note.project().direction==='rtl');return note});
  test(tests,'w4c.rich.canonical-clipboard-portable-interoperability',()=>{const learn=createStructuredConsumerAdapter('learn'),id=learn.snapshot().blocks[0].id;learn.selectBlocks([id]);const portable=learn.copySelectionPortable();assert(portable.ownership.clipboardOwner==='StructuredClipboardTrustOwner'&&!portable.ownership.clipboardOwnership&&portable.blocks.length===1);const canonical=learn.richContentOwner.canonicalClipboardFromPortable(portable,{documentId:'external-portable-proof',domainKind:'portable'});assert(canonical.validation.owner==='StructuredClipboardTrustOwner'&&canonical.validation.code==='AVAILABLE'&&!canonical.ownership.clipboardOwnership);return {portableOwnership:portable.ownership,canonicalValidation:canonical.validation}});
  test(tests,'w4c.rich.portable-paste-delegates-canonical-owner',()=>{const learn=createStructuredConsumerAdapter('learn'),before=learn.snapshot().blocks.length,id=learn.snapshot().blocks[0].id;learn.selectBlocks([id]);const portable=learn.copySelectionPortable(),result=learn.pastePortableRich(portable,before,{allocateId:({sourceId})=>`${sourceId}-portable-proof`});assert(result.document.blocks.length===before+1&&learn.clipboardReceipts().at(-1).owner==='StructuredClipboardTrustOwner');return {inserted:result.inserted,clipboardReceipt:learn.clipboardReceipts().at(-1)}});
  test(tests,'w4c.rich.no-second-clipboard-owner',()=>{for(const surface of ['learn']){const a=createStructuredConsumerAdapter(surface);assert(a.clipboardOwner.owner==='StructuredClipboardTrustOwner');assert(a.richContentOwner.owner==='StructuredRichContentOwner');assert(a.richContentOwner.descriptor().clipboardOwnership===false);assert(a.richContentOwner.clipboardOwner===a.clipboardOwner)}return {clipboardOwner:'StructuredClipboardTrustOwner',richClipboardOwnership:false}});
  test(tests,'w4c.rich.unsanitized-portable-active-html-never-leaks',()=>{const learn=createStructuredConsumerAdapter('learn'),portable={kind:STRUCTURED_RICH_SANITIZATION_POLICY.portableKind,version:1,blocks:[{id:'evil',type:'paragraph',html:'<img src=x onerror=evil()><script>boom()</script><strong onclick="x">safe</strong>'}]};const converted=learn.richContentOwner.canonicalClipboardFromPortable(portable,{documentId:'untrusted',domainKind:'portable'});const html=converted.payload.blocks[0].html;assert(html==='<strong>safe</strong>'&&!/script|onerror|onclick|<img/i.test(html));assert(converted.validation.owner==='StructuredClipboardTrustOwner');return {html,validation:converted.validation}});
  test(tests,'w4c.rich.no-domain-language-inference-through-owner',()=>{const resolver=new InputDirectionResolver({bridge:new PlatformInputDirectionBridge(()=> 'ltr')}),owner=new StructuredRichContentOwner({directionResolver:resolver}),a=owner.projectBlock({id:'mixed-a',type:'paragraph',html:'العربية English العربية'}),b=owner.projectBlock({id:'mixed-b',type:'paragraph',html:'English العربية English'});assert(a.direction==='ltr'&&b.direction==='ltr'&&!a.directionResolution.semanticInference&&!b.directionResolution.semanticInference);return {a:a.directionResolution,b:b.directionResolution}});
  test(tests,'w4c.rich.policy-identity',()=>{const owner=new StructuredRichContentOwner();assert(owner.descriptor().sanitizationPolicyRevision===STRUCTURED_RICH_SANITIZATION_POLICY.revision&&owner.descriptor().directionOwner==='InputDirectionResolver');return owner.descriptor()});
  const pass=tests.filter(x=>x.status==='PASS').length,fail=tests.length-pass;return {schemaVersion:1,classification:'W4_C_LANE_SPECIFIC_EXECUTABLE_PROOF_NOT_CONTROLLER_ACCEPTANCE',summary:{total:tests.length,pass,fail},tests};
}

if(import.meta.url===`file://${process.argv[1]}`){const receipt=runW4CDirectionRichContentTests();console.log(JSON.stringify(receipt,null,2));if(receipt.summary.fail)process.exitCode=1;}
